#### getProcesses (packages/wrangler/e2e/helpers/workerd-processes.ts:8)

```typescript
function getProcesses(): Process[] {
	return childProcess
		.execSync("ps -e | awk '{print $1,$4}'", { encoding: "utf8" })
		.trim()
		.split("\n")
		.map((line) => {
			const [pid, cmd] = line.split(" ");
			return { pid, cmd };
		});
}
```

#### getStartedWorkerdProcesses (packages/wrangler/e2e/helpers/workerd-processes.ts:26)

```typescript
export function getStartedWorkerdProcesses(cwd: string): Process[] {
	return getProcesses()
		.filter(({ cmd }) => cmd.includes("workerd"))
		.filter((c) => getProcessCwd(c.pid).includes(cwd));
}
